<?php
declare(strict_types=1); namespace Theobroma\OneC\Products;
final class ProductFields {private const FIELDS=['_theobroma_1c_guid'=>'GUID 1С','_theobroma_1c_article'=>'Артикул 1С','_theobroma_client_article'=>'Артикул клиента','_theobroma_ozon_product_id'=>'Ozon Product ID','_theobroma_ean'=>'EAN / штрихкод'];public function register():void{add_action('woocommerce_product_options_sku',[$this,'render']);add_action('woocommerce_admin_process_product_object',[$this,'save']);}public function render():void{echo'<p class="form-field"><strong>Внешние идентификаторы</strong></p>';foreach(self::FIELDS as$id=>$label)woocommerce_wp_text_input(['id'=>$id,'label'=>$label]);}public function save(\WC_Product $product):void{foreach(self::FIELDS as$id=>$label){if(!isset($_POST[$id]))continue;$value=trim(sanitize_text_field(wp_unslash((string)$_POST[$id])));if(in_array($id,['_theobroma_ozon_product_id','_theobroma_ean'],true)&&$value!==''&&!ctype_digit($value))continue;$value=mb_substr($value,0,191);$value===''?$product->delete_meta_data($id):$product->update_meta_data($id,$value);}}}
